// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint[] memory vs) public {
        vm.assume(contract_address != address(0) && contract_address != address(c));
        vm.assume(tos.length > 0 && vs.length > 0 && tos.length == vs.length);
        vm.assume(tos.length <= 4);
        vm.assume(contract_address.code.length == 0); // plain EOA callee: low-level call succeeds
        for (uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
            vm.assume(vs[i] < 2**250);
        }
        bool ok;
        bool ret;
        try c.transfer(contract_address, tos, vs) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
        }
        assertTrue(ok && ret, "transfer must complete and return true");
    }
}
